-- 0001_initial: PostgreSQL baseline converted from SCHEMA (server/accounts.js)
-- and LEDGER_SCHEMA (server/ledger.js).
--
-- Conversion rules (design.md, Components §4 and Data Models):
--   * Millisecond timestamps (SQLite INTEGER) become BIGINT.
--   * revision / people_count keep INTEGER (small values; the importer rejects
--     values outside int4 instead of truncating).
--   * audit.id AUTOINCREMENT becomes BIGINT GENERATED BY DEFAULT AS IDENTITY so
--     the SQLite importer can insert the original ids and then setval() the
--     sequence (Req 13.10).
--   * JSON payload columns (state_json, ledger_json, requests_json) stay TEXT so
--     stored bytes, requestHash and corruption checks behave exactly as before.
--
-- Runs inside a single transaction: no CONCURRENTLY, no non-transactional DDL.

CREATE TABLE users (
  id TEXT PRIMARY KEY,
  username TEXT NOT NULL UNIQUE,
  display_name TEXT NOT NULL,
  role TEXT NOT NULL CHECK (role IN ('admin', 'member')),
  password_hash TEXT NOT NULL,
  created_at BIGINT NOT NULL,
  deleted_at BIGINT
);

CREATE TABLE sessions (
  token_hash TEXT PRIMARY KEY,
  user_id TEXT NOT NULL REFERENCES users(id),
  created_at BIGINT NOT NULL,
  expires_at BIGINT NOT NULL
);
CREATE INDEX sessions_user ON sessions(user_id);

CREATE TABLE trips (
  id TEXT PRIMARY KEY,
  owner_id TEXT NOT NULL REFERENCES users(id),
  title TEXT NOT NULL,
  destination TEXT NOT NULL,
  start_date TEXT NOT NULL,
  end_date TEXT NOT NULL,
  description TEXT NOT NULL,
  note TEXT NOT NULL,
  cover_kind TEXT NOT NULL CHECK (cover_kind IN ('camp', 'mountain', 'lake', 'night')),
  status TEXT NOT NULL CHECK (status IN ('planning', 'completed')),
  revision INTEGER NOT NULL,
  people_count INTEGER NOT NULL,
  state_json TEXT NOT NULL,
  created_at BIGINT NOT NULL,
  updated_at BIGINT NOT NULL
);

CREATE TABLE trip_members (
  trip_id TEXT NOT NULL REFERENCES trips(id),
  user_id TEXT NOT NULL REFERENCES users(id),
  person_id TEXT NOT NULL,
  joined_at BIGINT NOT NULL,
  PRIMARY KEY (trip_id, user_id),
  UNIQUE (trip_id, person_id)
);
CREATE INDEX trip_members_user ON trip_members(user_id);

CREATE TABLE invites (
  token_hash TEXT PRIMARY KEY,
  trip_id TEXT NOT NULL REFERENCES trips(id),
  created_by TEXT NOT NULL REFERENCES users(id),
  created_at BIGINT NOT NULL,
  expires_at BIGINT NOT NULL,
  revoked_at BIGINT
);
CREATE INDEX invites_trip ON invites(trip_id);

CREATE TABLE trip_deletions (
  trip_id TEXT PRIMARY KEY REFERENCES trips(id),
  deleted_by TEXT NOT NULL REFERENCES users(id),
  deleted_at BIGINT NOT NULL
);

CREATE TABLE audit (
  id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  at BIGINT NOT NULL,
  actor TEXT NOT NULL,
  action TEXT NOT NULL,
  target TEXT NOT NULL
);

CREATE TABLE trip_ledgers (
  trip_id TEXT PRIMARY KEY REFERENCES trips(id),
  revision INTEGER NOT NULL CHECK (revision >= 1),
  ledger_json TEXT NOT NULL,
  requests_json TEXT NOT NULL,
  updated_by TEXT NOT NULL REFERENCES users(id),
  updated_at BIGINT NOT NULL
);
